+            let first = local.moves.first().map(|m| m.from.x.hypot(m.from.y)).unwrap_or(0.0);
+            assert!(first >= raw + 5.0 - 1e-9, "{word} raw r{raw:.2}: the clearance stands off the stock: {first:.3}");
